function build(text, order){
  order=order>0?order:2;
  var words=(text||'').split(/\s+/).filter(function(w){return w.length;});
  if(words.length<order+1) return null;
  var map={};
  for(var i=0;i+order<words.length;i++){
    var key=words.slice(i,i+order).join(' ');
    var next=words[i+order];
    (map[key]=map[key]||[]).push(next);
  }
  return {map:map, order:order, start:words.slice(0,order).join(' ')};
}
function gen(model, rng, n){
  if(!model||!(n>0)) return '';
  var keys=Object.keys(model.map); if(!keys.length) return '';
  var cur=model.start && model.map[model.start] ? model.start : keys[Math.floor(rng()*keys.length)];
  var out=cur.split(' ');
  for(var i=0;i<n;i++){
    var opts=model.map[cur]; if(!opts||!opts.length) break;
    var nxt=opts[Math.floor(rng()*opts.length)];
    out.push(nxt);
    cur=out.slice(out.length-model.order).join(' ');
  }
  return out.join(' ');
}
var EXPORTS={build:build,gen:gen};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MarkovGenForgePure = EXPORTS; }
